/** The items' motion, scoped to .jzc; every rule stops under prefers-reduced-motion. */
export const COSMETICS_MOTION_CSS = ".jzc .lg-glow{animation:jzc-lgGlow 2.4s ease-in-out infinite}\n@keyframes jzc-lgGlow{0%,100%{opacity:.75}50%{opacity:1}}.jzc .lg-tw{animation:jzc-lgTw 2.6s ease-in-out infinite}.jzc .lg-tw2{animation-delay:-.9s}.jzc .lg-tw3{animation-delay:-1.7s}\n@keyframes jzc-lgTw{0%,100%{opacity:.25}50%{opacity:1}}.jzc .lg-zap{animation:jzc-lgZap 1.7s steps(1) infinite}.jzc .lg-zap2{animation-delay:-.6s}.jzc .lg-zap3{animation-delay:-1.1s}\n@keyframes jzc-lgZap{0%{opacity:0}12%{opacity:1}18%{opacity:0}46%{opacity:1}50%{opacity:0}78%{opacity:.8}84%{opacity:0}100%{opacity:0}}.jzc .cl-fall{animation:jzc-clFall 3s linear infinite}\n@keyframes jzc-clFall{from{transform:translateY(-20px)}to{transform:translateY(40px)}}\n@media (prefers-reduced-motion: reduce){.jzc .lg-glow,.jzc .lg-tw,.jzc .cl-fall{animation:none}.jzc .lg-zap{animation:none;opacity:.8}}\n.jzc[data-rest] *{animation:none !important}.jzc[data-rest] .lg-zap{opacity:.8}";
